      username: "target",
      password: targetPassword,
      name: "Target",
    });
    expect(targetUserRes.status).toBe(201);

    const ownerSessionRes = await request("POST", "/sessions", undefined, {
      username: "owner",
      password: ownerPassword,
    });
    expect(ownerSessionRes.status).toBe(201);
    const ownerToken = (await ownerSessionRes.json()).token as string;

    const targetSessionRes = await request("POST", "/sessions", undefined, {
      username: "target",
      password: targetPassword,
    });
    expect(targetSessionRes.status).toBe(201);
    const targetToken = (await targetSessionRes.json()).token as string;

    const repoRes = await request("POST", "/repos", ownerToken, {
      name: "repo",
      visibility: "private",
    });
    expect(repoRes.status).toBe(201);

    const addRes = await request(
      "PUT",
      "/repos/owner/repo/collaborators/target",
      ownerToken,
      { role: "admin" },
    );
    expect(addRes.status).toBe(201);

    const warmRes = await request("GET", "/repos/owner/repo", targetToken);
    console.log(`[probe] target GET /repos/owner/repo -> ${warmRes.status} (expected 200)`);
    expect(warmRes.status).toBe(200);

    const revokeRes = await request(
      "DELETE",
      "/repos/owner/repo/collaborators/target",
      ownerToken,
    );
    if (revokeRes.status === 404) {
      const ct = revokeRes.headers.get("content-type") ?? "";
      const body = await revokeRes.text();
      if (ct.startsWith("text/plain") && body === "404 Not Found") {
        console.log(`[probe] owner DELETE /repos/owner/repo/collaborators/target -> ${revokeRes.status} (expected n/a)`);
