      }
    }
    console.log(`[probe] owner DELETE /repos/owner/repo/collaborators/target -> ${revokeRes.status} (expected 204)`);
    expect(revokeRes.status).toBe(204);

    const afterRes = await request("GET", "/repos/owner/repo", targetToken);
    console.log(`[probe] target GET /repos/owner/repo -> ${afterRes.status} (expected 404)`);
    expect(afterRes.status).toBe(404);
  });
});
"}, "rationale": "The probe sets up an owner, a target user, a private repository, and makes the target an admin collaborator. The target reads the repository once to warm any per-session role cache, the owner revokes the target using A's DELETE route, and the target reads the repository again in the same session. In A's world, requirePermission evaluates the caller's role from the store on every request, so the second read returns 404; in A+B, B's per-session cache still supplies the cached admin role and the read returns 200, causing the 404 expectation to fail. If the revoke route is absent (base or B alone), the DELETE request receives Hono's default text/plain 404, which signals n/a. The test also fails if A's revoke does nothing, because the target would still be allowed."}

